exercise.referenceSolution:
#include <stdio.h>

static int count;
static long long sum;
static int max;

void record(int x) {
    if (count == 0 || x > max) {
        max = x;
    }
    count++;
    sum += x;
}

void report(void) {
    if (count == 0) {
        printf("count=0\n");
    } else {
        printf("count=%d sum=%lld max=%d\n", count, sum, max);
    }
}

int main(void) {
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        record(x);
    }
    report();
    return 0;
}

