additionalExercises.referenceSolution:
#include <stdio.h>

double moving_average(int x) {
    static int last[3];
    static int stored = 0;
    static int pos = 0;
    last[pos] = x;
    pos = (pos + 1) % 3;
    if (stored < 3) {
        stored++;
    }
    int sum = 0;
    for (int i = 0; i < stored; i++) {
        sum += last[i];
    }
    return (double)sum / stored;
}

int main(void) {
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        printf("%.2f\n", moving_average(x));
    }
    return 0;
}

